Definition const (v_consttype : consttype) (v_lit_ : lit_) : instr :=
	match v_consttype, v_lit_ return instr with
		| consttype_I32, (mk_lit__0 numtype_I32 c) => (instr_CONST numtype_I32 c)
		| consttype_I64, (mk_lit__0 numtype_I64 c) => (instr_CONST numtype_I64 c)
		| consttype_F32, (mk_lit__0 F32 c) => (instr_CONST F32 c)
		| consttype_F64, (mk_lit__0 F64 c) => (instr_CONST F64 c)
		| consttype_V128, (mk_lit__1 V128 c) => (instr_VCONST V128 c)
		| _, _ => default_val
	end.

