with

Instrs_ok : context -> (seq instr) -> instrtype -> Prop :=
	| Instrs_ok__empty : forall (C : context), 
		(wf_context C) ->
		(wf_instrtype (mk_instrtype (mk_list _ [:: ]) [:: ] (mk_list _ [:: ]))) ->
		Instrs_ok C [:: ] (mk_instrtype (mk_list _ [:: ]) [:: ] (mk_list _ [:: ]))
	| Instrs_ok__instr : forall (C : context) (v_instr : instr) (t_1_lst : (seq valtype)) (x_lst : (seq idx)) (t_2_lst : (seq valtype)), 
		(Instr_ok C v_instr (mk_instrtype (mk_list _ t_1_lst) x_lst (mk_list _ t_2_lst))) ->
		(wf_context C) ->
		(wf_instr v_instr) ->
		(wf_instrtype (mk_instrtype (mk_list _ t_1_lst) x_lst (mk_list _ t_2_lst))) ->
		Instrs_ok C [::v_instr] (mk_instrtype (mk_list _ t_1_lst) x_lst (mk_list _ t_2_lst))
	| res_seq : forall (C : context) (instr_1_lst : (seq instr)) (instr_2_lst : (seq instr)) (t_1_lst : (seq valtype)) (x_1_lst : (seq idx)) (x_2_lst : (seq idx)) (t_3_lst : (seq valtype)) (t_2_lst : (seq valtype)) (init_lst : (seq init)) (t_lst : (seq valtype)) (var_0 : (option context)), 
		(fun_with_locals C x_1_lst (seq.map (fun (t : valtype) => (mk_localtype SET t)) t_lst) var_0) ->
		(Instrs_ok C instr_1_lst (mk_instrtype (mk_list _ t_1_lst) x_1_lst (mk_list _ t_2_lst))) ->
		((|init_lst|) == (|t_lst|)) ->
		((|init_lst|) == (|x_1_lst|)) ->
		List.Forall (fun (x_1 : idx) => ((x_1 :> nat) < (|(context_LOCALS C)|))%N) x_1_lst ->
		List_Forall3 (fun (v_init : init) (t : valtype) (x_1 : idx) => (((context_LOCALS C)[| (x_1 :> nat) |]) == (mk_localtype v_init t))) init_lst t_lst x_1_lst ->
		(var_0 != None) ->
		(Instrs_ok (!(var_0)) instr_2_lst (mk_instrtype (mk_list _ t_2_lst) x_2_lst (mk_list _ t_3_lst))) ->
		(wf_context C) ->
		List.Forall (fun (instr_1 : instr) => (wf_instr instr_1)) instr_1_lst ->
		List.Forall (fun (instr_2 : instr) => (wf_instr instr_2)) instr_2_lst ->
		(wf_context (!(var_0))) ->
		(wf_instrtype (mk_instrtype (mk_list _ t_1_lst) (x_1_lst ++ x_2_lst) (mk_list _ t_3_lst))) ->
		(wf_instrtype (mk_instrtype (mk_list _ t_1_lst) x_1_lst (mk_list _ t_2_lst))) ->
		List.Forall2 (fun (v_init : init) (t : valtype) => (wf_localtype (mk_localtype v_init t))) init_lst t_lst ->
		List.Forall (fun (t : valtype) => (wf_localtype (mk_localtype SET t))) t_lst ->
